def mse(w, b, xs, ys):
    return sum((y - (w * x + b)) ** 2 for x, y in zip(xs, ys)) / len(xs)

def lowest_w(ws, xs, ys):
    best_w, best_loss = None, float('inf')
    for w in ws:
        loss = mse(w, 0, xs, ys)
        if loss < best_loss:
            best_w, best_loss = w, loss
    return best_w

